#!/usr/bin/env bash
# Copy the agent skills generated by the local_mcpcourse plugin into skills/, then refresh the scenario list of the site.
#
# Usage: scripts/sync-skills.sh <path to the plugin> [version]
#
# [version] (for example 2.5.2) is written to .claude-plugin/plugin.json: give the version of the release the skills belong to.
# Without it, the script reads `release` in the plugin's version.php, only when it is a release (a -dev one is ignored).
#
# The plugin generates its skills (agent-kit/skills, from its scenario catalog); this repository only publishes them.
# Never edit skills/ by hand: change the plugin, then run this script again.
set -euo pipefail

if [ "$#" -lt 1 ] || [ "$#" -gt 2 ]; then
  echo "usage: $0 <path to the local_mcpcourse plugin> [version]" >&2
  exit 2
fi

plugin="${1%/}"
src="$plugin/agent-kit/skills"
root="$(cd "$(dirname "$0")/.." && pwd)"
dest="$root/skills"

if [ ! -d "$src" ]; then
  echo "ERROR: $src does not exist: give the path of a local_mcpcourse checkout that has agent-kit/skills." >&2
  exit 1
fi
if ! ls "$src"/*/SKILL.md >/dev/null 2>&1; then
  echo "ERROR: no */SKILL.md under $src." >&2
  exit 1
fi

# A symbolic link in the generated skills would copy a file of this machine into a public zip: refuse it.
if [ -n "$(find "$src" -type l -print -quit)" ]; then
  echo "ERROR: symbolic link under $src:" >&2
  find "$src" -type l >&2
  exit 1
fi

tmp="$(mktemp -d)"
trap 'rm -rf "$tmp"' EXIT
for dir in "$src"/*/; do
  name="$(basename "$dir")"
  [ -f "$dir/SKILL.md" ] || continue
  cp -R -P "$dir" "$tmp/$name"
done

# Replace skills/ as a whole, keeping only its README.
find "$dest" -mindepth 1 -maxdepth 1 -type d -exec rm -rf {} +
cp -R "$tmp"/. "$dest"/
echo "Skills copied from $src:"
for dir in "$dest"/*/; do echo "  $(basename "$dir")"; done

# Check the copied skills against the Agent Skills specification (YAML parser from the root package).
if command -v npm >/dev/null 2>&1; then
  (cd "$root" && npm ci --no-audit --no-fund --silent && node scripts/check-skills.mjs)
else
  docker run --rm --user "$(id -u):$(id -g)" -e HOME=/tmp -v "$root:/repo" -w /repo node:22-slim \
    sh -c 'npm ci --no-audit --no-fund --silent && node scripts/check-skills.mjs'
fi

# Align the version of the Claude Code plugin manifest with the skills.
version="${2:-}"
if [ -z "$version" ] && [ -f "$plugin/version.php" ]; then
  version="$(sed -nE "s/^.*->release *= *'([0-9]+\.[0-9]+\.[0-9]+)'.*$/\1/p" "$plugin/version.php" | head -n 1)"
fi
if [[ "$version" =~ ^[0-9]+\.[0-9]+\.[0-9]+$ ]]; then
  sed -i -E "s/(\"version\": *\")[^\"]*(\")/\1$version\2/" "$root/.claude-plugin/plugin.json"
  echo ".claude-plugin/plugin.json: version $version"
else
  echo "WARNING: no valid version (give it as the second argument): plugin.json was not updated." >&2
fi

# Refresh the scenario list of the site from the same plugin.
if command -v php >/dev/null 2>&1; then
  php "$root/scripts/export-scenarios.php" "$plugin"
elif command -v docker >/dev/null 2>&1; then
  docker run --rm --user "$(id -u):$(id -g)" -v "$plugin:/plugin:ro" -v "$root:/repo" -w /repo php:8.3-cli \
    php scripts/export-scenarios.php /plugin site/data/scenarios.json
else
  echo "WARNING: neither php nor docker: site/data/scenarios.json was not refreshed." >&2
fi
